module multi_pipe_4bit(
    input clk, input rst_n,
    input [3:0] mul_a, mul_b,
    output reg [7:0] mul_out
);
    parameter size = 4;
    reg [size-1:0] mul_a_reg;
    reg [size-1:0] mul_b_reg;
    reg [2*size-1:0] mul_out_reg;
    reg [2*size-1:0] partial_product_reg;
    reg [2*size-1:0] register_reg;
    reg [2*size-1:0] partial_product [size-1:0];
    reg [2*size-1:0] register;
    reg [2*size-1:0] partial_product_sum;
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_a_reg <= 4'd0;
            mul_b_reg <= 4'd0;
            mul_out_reg <= 8'd0;
            partial_product_reg <= 8'd0;
            register_reg <= 8'd0;
        end else begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_out_reg <= mul_out_reg;
            partial_product_reg <= partial_product_sum;
            register_reg <= register;
        end
    end
    always @(*) begin
        for (i = 0; i < size; i = i + 1) begin
            partial_product[i] = (mul_b_reg[i] == 1) ? (mul_a_reg << i) : 'd0;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out_reg <= 'd0;
        end else begin
            mul_out_reg <= register_reg;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            register_reg <= 'd0;
        end else begin
            register_reg <= partial_product_reg + register;
        end
    end
    always @(*) begin
        partial_product_sum = partial_product[0];
        for (i = 1; i < size; i = i + 1) begin
            partial_product_sum = partial_product_sum + partial_product[i];
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_out <= 8'd0;
        end else begin
            mul_out <= mul_out_reg;
        end
    end
endmodule
